/**
 * One end of a link a graph action names: a node, one of its ports, and the member of a bundle
 * port it starts or ends at, if any.
 */
export interface StreamGraphActionLinkEnd {
  /**
   * The node, by the UUID `graph` lists as its `id` and `add_node` answers; in `transact`, also the `as` of a node an earlier `add_node` of the same transaction adds.
   */
  node: string;
  /**
   * The port's name, as `graph` lists it under the node's `ports`.
   */
  port: string;
  /**
   * The member of a bundle port the link starts or ends at, as `graph` lists it under the port's `pin_type`; omitted for the whole port. A bundle input is fed either whole or member by member, and the node reads one bundle built from the newest value of each member.
   */
  member?: string | null;
}

/**
 * Whether a graph edit is kept.
 */
export type GraphEditMode = "commit" | "live";

/**
 * A change's author as a caller names it.
 */
export interface ProjectTransactionAuthorArgument {
  /**
   * `person` or `agent`.
   */
  kind: ProjectTransactionAuthorKindArgument;
  /**
   * The author's name as history shows it.
   */
  name: string;
}

/**
 * Who a change is by, as a caller names it.
 */
export type ProjectTransactionAuthorKindArgument = "person" | "agent";

/**
 * The result of a graph tool: the transaction it applied, committed or live.
 */
export interface GraphTransactionToolResult {
  /**
   * `commit`, written to the graph documents and recorded in history, or `live`, applied
   * to the running streams alone.
   */
  mode: string;
  /**
   * The transaction's UUID; absent on a live one, which history never records.
   */
  transaction?: string | null;
  /**
   * The commit on the project history's `main` that records it; absent on a live one.
   */
  commit?: string | null;
  /**
   * Each operation as applied, in order, tagged by its `operation`, its `stream` by
   * stream id.
   */
  operations: Array<unknown>;
  /**
   * Each node it added.
   */
  added_nodes: Array<GraphTransactionAddedNode>;
  /**
   * Each link it made.
   */
  connected_links: Array<GraphTransactionConnectedLink>;
  /**
   * Each labelled group it made.
   */
  added_groups?: Array<GraphTransactionAddedGroup>;
  /**
   * Each canvas note it placed.
   */
  added_notes?: Array<GraphTransactionAddedNote>;
  /**
   * Each node it built again to take a setting read at setup.
   */
  nodes_rebuilt?: Array<GraphTransactionRebuiltNode>;
  /**
   * Each input it set a value on that a link feeds, whose messages the node reads instead.
   */
  overridden_by_links?: Array<GraphTransactionInputOverriddenByALink>;
  /**
   * Each saved value of a `GraphInput` it carried into the pin type it chose for it.
   */
  saved_values_retyped?: Array<GraphTransactionSavedValueRetyped>;
}

/**
 * A node a graph transaction added.
 */
export interface GraphTransactionAddedNode {
  /**
   * The stream it was added to, by stream id.
   */
  stream: string;
  /**
   * The UUID the runtime made for it.
   */
  node: string;
  /**
   * The name it took.
   */
  name: string;
  /**
   * The `as` its `add_node` gave it, which later operations of the transaction named it by.
   */
  as?: string | null;
  /**
   * Its node type, on a node a `connect` inserted.
   */
  node_type?: string;
  /**
   * Why a `connect` inserted it on its link.
   */
  inserted_because?: GraphTransactionNodeInsertedBecause;
}

/**
 * Why a `connect` placed a node of its own on the link it asked for, the link carried through
 * it. The set grows: a reason a client does not know reads as `for_another_reason`.
 */
export type GraphTransactionNodeInsertedBecause = "converts_pin_types" | "closes_a_loop" | "for_another_reason";

/**
 * A link a graph transaction made, with the state the stream's graph reads it in.
 */
export interface GraphTransactionConnectedLink {
  /**
   * The stream it was made in, by stream id.
   */
  stream: string;
  /**
   * The output port it carries from.
   */
  source: GraphLinkEndOnTheWire;
  /**
   * The input port it carries into.
   */
  target: GraphLinkEndOnTheWire;
  /**
   * `pending`, `wired` or `error`; absent when the graph could not be read after it.
   */
  state?: string | null;
  /**
   * Why a link reading `error` will carry nothing, in the refusing end's own words.
   */
  error_reason?: string | null;
  /**
   * `true` when the input reads what the output carries as its own type at no cost: Boolean,
   * Integer and Float among themselves, a Vector into a Vector or a Color, one number into a
   * Vector or a Color, or a Menu into a String. Absent on every other link.
   */
  free_conversion?: boolean;
  /**
   * What the link does that a person may not expect, as the judgement of its two ends' pin
   * types says; none of these blocks it. Absent when it warns of nothing.
   */
  warnings?: Array<PinLinkWarningOnTheWire>;
  /**
   * Why the link was saved without its two ends being judged, when it was: inside a placed
   * stream, it reaches a node that runs as no node of its own, or one that is not built to
   * judge it, such as one whose type is not described.
   */
  not_judged_because?: string | null;
}

/**
 * A labelled group a graph transaction made.
 */
export interface GraphTransactionAddedGroup {
  /**
   * The stream it was made in, by stream id.
   */
  stream: string;
  /**
   * The UUID the runtime made for it.
   */
  group: string;
  /**
   * Its title.
   */
  title: string;
}

/**
 * A canvas note a graph transaction placed.
 */
export interface GraphTransactionAddedNote {
  /**
   * The stream it was placed in, by stream id.
   */
  stream: string;
  /**
   * The UUID the runtime made for it.
   */
  note: string;
}

/**
 * A node a graph transaction built again, so it reads a setting it takes only when it is set
 * up.
 */
export interface GraphTransactionRebuiltNode {
  /**
   * The stream the node is in, by stream id.
   */
  stream: string;
  /**
   * The node's UUID.
   */
  node: string;
}

/**
 * An input a graph transaction set a value on while a link feeds it, so the link's messages
 * are what the node reads until the link is taken out.
 */
export interface GraphTransactionInputOverriddenByALink {
  /**
   * The stream the node is in, by stream id.
   */
  stream: string;
  /**
   * The node's UUID.
   */
  node: string;
  /**
   * The input set.
   */
  input: string;
  /**
   * The UUID of the node the link carries from.
   */
  from_node: string;
  /**
   * The output port the link carries from.
   */
  from_output: string;
}

/**
 * The saved value of a top-level `GraphInput` that a graph transaction carried into the pin
 * type it chose for it: cast by the one conversion that fits the two types, or given up for the
 * new type's default, which is no saved value.
 */
export interface GraphTransactionSavedValueRetyped {
  /**
   * The stream the `GraphInput` is in, by stream id.
   */
  stream: string;
  /**
   * The `GraphInput`'s UUID.
   */
  node: string;
  /**
   * The value it saved under its former type.
   */
  value_before: unknown;
  /**
   * The value it saves under its new type, held within its `range`; absent when it gave way to
   * the new type's default.
   */
  value?: unknown;
  /**
   * The node type of the conversion that cast it; absent when none did.
   */
  cast_by?: string | null;
  /**
   * Why it gave way to the new type's default; absent when it was cast.
   */
  default_because?: string | null;
  /**
   * The node type of each conversion that fits the two types, when it gave way to the default
   * though one or more fit.
   */
  conversions_that_fit?: Array<string>;
}

/**
 * `add_node`'s params.
 */
export interface AddNodeRequest {
  /**
   * The stream the edit is to: the stream id `list_streams` answers as `stream`, or its stream asset's UUID, the `asset` its graph document holds, which `list_streams` reports as its `location`'s `stream_asset`. A string in UUID form names a stream asset, and any other a stream id. A name that matches no stream the runtime holds is refused with `stream_not_found`, naming the ones it holds.
   */
  stream: string;
  /**
   * The subgraph the edit is inside, as the path of fragment node UUIDs from the stream's own level inward, each one `graph` lists as an `id` at the level before it; omit it, or send `[]`, for the stream's own level. Each node on the path places a stream of the project, and the edit is made on the document of the stream the last one places, which every stream placing it takes; the edit is made with `mode` `commit`. A graph generator's output is refused until `unlock_subgraph`, and a stream placed from an import is edited in the import's own project.
   */
  level?: Array<string> | null;
  /**
   * The node's type by its import path, e.g. `nodes.grayscale_effect:GrayscaleEffect`, as `graph` reports it and `list_node_types` lists it.
   */
  type: string;
  /**
   * The node's name, a label: cast to lowercase URL-safe (`Front Camera` becomes `front-camera`) and refused when another node has it. Omit it for the type's short name, cast, with the next free `-2`, `-3` …
   */
  name?: string | null;
  /**
   * What Tato Studio draws the node with, under the studio contract: `position` an `[x, y]` pair of numbers, `group` a labelled group's UUID, `comment` and `colour` strings, `collapsed` a bool, and anything else a client keeps under `metadata`, an object kept as given. A key of the wrong shape, or any other key, is refused by name.
   */
  studio?: { [key: string]: unknown } | null;
  /**
   * `commit`, the default: the edit is applied to the running stream, written to the stream's graph document and recorded as one commit on the project's history, so it is kept on the next load and undo reverses it. `live`: applied to the running stream alone, never in history, and gone on the next load, except a value set live on a `kept` input, which is held across a Stop and the next load while a `reset` input forgets its one at Stop. Send a continuous gesture as one transaction when it ends.
   */
  mode?: GraphEditMode | null;
  /**
   * Who the change is by, as history records it and undo follows it. Omit it to be the agent the MCP client named in its `clientInfo`.
   */
  author?: ProjectTransactionAuthorArgument | null;
  /**
   * A key the caller mints once per user gesture, such as a slider drag committed on release. Sent again under a key the project's history holds, the action applies nothing and answers the transaction the key first applied. Omit it to apply the action each time it is sent. A `live` edit is never recorded, so its key is not kept.
   */
  idempotency_key?: string | null;
}

/**
 * The params of an edit naming one link: `connect`'s, and `disconnect`'s.
 */
export interface OneLinkGraphEditRequest {
  /**
   * The stream the edit is to: the stream id `list_streams` answers as `stream`, or its stream asset's UUID, the `asset` its graph document holds, which `list_streams` reports as its `location`'s `stream_asset`. A string in UUID form names a stream asset, and any other a stream id. A name that matches no stream the runtime holds is refused with `stream_not_found`, naming the ones it holds.
   */
  stream: string;
  /**
   * The subgraph the edit is inside, as the path of fragment node UUIDs from the stream's own level inward, each one `graph` lists as an `id` at the level before it; omit it, or send `[]`, for the stream's own level. Each node on the path places a stream of the project, and the edit is made on the document of the stream the last one places, which every stream placing it takes; the edit is made with `mode` `commit`. A graph generator's output is refused until `unlock_subgraph`, and a stream placed from an import is edited in the import's own project.
   */
  level?: Array<string> | null;
  /**
   * The output port the link carries from: a node's UUID and its output port's name.
   */
  source: StreamGraphActionLinkEnd;
  /**
   * The input port the link carries into: a node's UUID and its input port's name.
   */
  target: StreamGraphActionLinkEnd;
  /**
   * `commit`, the default: the edit is applied to the running stream, written to the stream's graph document and recorded as one commit on the project's history, so it is kept on the next load and undo reverses it. `live`: applied to the running stream alone, never in history, and gone on the next load, except a value set live on a `kept` input, which is held across a Stop and the next load while a `reset` input forgets its one at Stop. Send a continuous gesture as one transaction when it ends.
   */
  mode?: GraphEditMode | null;
  /**
   * Who the change is by, as history records it and undo follows it. Omit it to be the agent the MCP client named in its `clientInfo`.
   */
  author?: ProjectTransactionAuthorArgument | null;
  /**
   * A key the caller mints once per user gesture, such as a slider drag committed on release. Sent again under a key the project's history holds, the action applies nothing and answers the transaction the key first applied. Omit it to apply the action each time it is sent. A `live` edit is never recorded, so its key is not kept.
   */
  idempotency_key?: string | null;
}

/**
 * `check_link`'s params: the link `connect` takes, without what a kept edit carries.
 */
export interface CheckLinkRequest {
  /**
   * The stream the edit is to: the stream id `list_streams` answers as `stream`, or its stream asset's UUID, the `asset` its graph document holds, which `list_streams` reports as its `location`'s `stream_asset`. A string in UUID form names a stream asset, and any other a stream id. A name that matches no stream the runtime holds is refused with `stream_not_found`, naming the ones it holds.
   */
  stream: string;
  /**
   * The subgraph the link would be inside, by the fragment nodes leading to it; omitted or empty for the stream's own level.
   */
  level?: Array<string> | null;
  /**
   * The output port the link would carry from: a node's UUID and its output port's name.
   */
  source: StreamGraphActionLinkEnd;
  /**
   * The input port the link would carry into: a node's UUID and its input port's name.
   */
  target: StreamGraphActionLinkEnd;
}

/**
 * `check_link`'s answer: whether and how `connect` would make the link, and the refusal it
 * would answer when it would not.
 */
export interface LinkCheckResult {
  /**
   * Whether and how `connect` would make the link.
   */
  outcome: PinLinkOutcomeOnTheWire;
  /**
   * The convert node `connect` would place between the two ends; present only when
   * `outcome` is `connects_through_convert_node`.
   */
  convert_node?: ConvertNodeToInsertOnTheWire | null;
  /**
   * The whole refusal `connect` would answer, with its code; present only when `outcome` is
   * `refused`.
   */
  refusal?: ControlOperationRefusalOnTheWire | null;
  /**
   * What the link would do that a person may not expect; none of these blocks it.
   */
  warnings?: Array<PinLinkWarningOnTheWire>;
}

/**
 * Whether and how a link connects. The set grows: an outcome a client does not know reads as
 * `refused`.
 */
export type PinLinkOutcomeOnTheWire = "connects" | "connects_with_free_conversion" | "connects_through_convert_node" | "refused";

/**
 * The node of one built-in conversion a link is made through.
 */
export interface ConvertNodeToInsertOnTheWire {
  /**
   * The node type that converts.
   */
  node_type: string;
  /**
   * The input the link's output feeds.
   */
  input_port: string;
  /**
   * The type that input takes.
   */
  input_pin_type: PinType;
  /**
   * The output that feeds the link's input.
   */
  output_port: string;
  /**
   * The type that output gives, under the settings `input_values` holds.
   */
  output_pin_type: PinType;
  /**
   * The settings the node holds, each by its input's name, picked for the link's input; absent
   * when what its output gives follows no setting.
   */
  input_values?: { [key: string]: unknown };
}

/**
 * `check_link_candidates`'s params: one placed end and the ends of the other direction it is
 * judged against.
 */
export interface CheckLinkCandidatesRequest {
  /**
   * The stream the edit is to: the stream id `list_streams` answers as `stream`, or its stream asset's UUID, the `asset` its graph document holds, which `list_streams` reports as its `location`'s `stream_asset`. A string in UUID form names a stream asset, and any other a stream id. A name that matches no stream the runtime holds is refused with `stream_not_found`, naming the ones it holds.
   */
  stream: string;
  /**
   * The subgraph the links would be inside, by the fragment nodes leading to it; omitted or empty for the stream's own level, the only level checked yet: a non-empty `level` is refused.
   */
  level?: Array<string> | null;
  /**
   * The placed end each candidate is judged against.
   */
  from: LinkCandidatesFrom;
  /**
   * The candidate ends.
   */
  among: LinkCandidatesAmong;
  /**
   * Whether a candidate `connect` would refuse is listed too, with the refusal it would answer; false or omitted lists only the candidates that connect.
   */
  include_refused?: boolean;
}

/**
 * The placed end `check_link_candidates` judges each candidate against, by its direction.
 */
export type LinkCandidatesFrom = {
  output: StreamGraphActionLinkEnd;
} | {
  input: StreamGraphActionLinkEnd;
};

/**
 * The candidate ends `check_link_candidates` judges, each of the direction other than its
 * placed end's.
 */
export type LinkCandidatesAmong = "placed_ports" | "node_type_ports" | {
  ends: Array<LinkCandidateEnd>;
};

/**
 * One end `check_link_candidates` judges its placed end against, of the other direction.
 */
export type LinkCandidateEnd = ({
  /**
   * The node, by the UUID `graph` lists as its `id`.
   */
  node: string;
  /**
   * The port's name, as `graph` lists it under the node's `ports`.
   */
  port: string;
  /**
   * The member of the bundle the port carries that the end is, by name; absent for
   * the whole port.
   */
  member?: string | null;
  kind: "placed_port";
}) | ({
  /**
   * The node type, by the import path `add_node` takes as its `type`.
   */
  node_type: string;
  /**
   * The port's name, as the node type declares it.
   */
  port: string;
  /**
   * The member of the bundle the port carries that the end is, by name; absent for
   * the whole port.
   */
  member?: string | null;
  kind: "node_type_port";
});

/**
 * `check_link_candidates`'s answer: for each candidate end, in the order judged, what
 * `check_link` would answer for its link with the placed end.
 */
export interface LinkCandidatesCheckResult {
  /**
   * Each candidate checked; one `connect` would refuse is listed only when the request set
   * `include_refused`.
   */
  candidates: Array<LinkCandidateChecked>;
  /**
   * Each candidate whose link is not checked yet, as `check_link` would not check it.
   */
  not_checked?: Array<LinkCandidateNotChecked>;
}

/**
 * One candidate end and what `check_link` would answer for the link between it and the placed
 * end.
 */
export interface LinkCandidateChecked {
  /**
   * The candidate end.
   */
  end: LinkCandidateEnd;
  /**
   * What `check_link` would answer for the link.
   */
  check: LinkCheckResult;
}

/**
 * One candidate end whose link `check_link` would not check yet, and why.
 */
export interface LinkCandidateNotChecked {
  /**
   * The candidate end.
   */
  end: LinkCandidateEnd;
  /**
   * Why the link is not checked yet, in the runtime's words.
   */
  why: string;
}

